import { lazy, Suspense } from "react";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { AuthProvider, useAuth } from "@/hooks/useAuth";
import { useFeatureFlag } from "@/hooks/useFeatureFlags";
import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
import { ThemeProvider } from "@/components/ThemeProvider";
import MaintenancePage from "@/components/MaintenancePage";
import SeoHead from "@/components/SeoHead";
import ChatWidget from "@/components/ChatWidget";

// Lazy-loaded route components for code splitting
const Index = lazy(() => import("./pages/Index"));
const Auth = lazy(() => import("./pages/Auth"));
const Admin = lazy(() => import("./pages/Admin"));
const Settings = lazy(() => import("./pages/Settings"));
const Profile = lazy(() => import("./pages/Profile"));
const Billing = lazy(() => import("./pages/Billing"));
const NotFound = lazy(() => import("./pages/NotFound"));
const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
const BookDemo = lazy(() => import("./pages/BookDemo"));
const RequestFeature = lazy(() => import("./pages/RequestFeature"));
const Changelog = lazy(() => import("./pages/Changelog"));
const Apply = lazy(() => import("./pages/Apply"));
const LandingPage = lazy(() => import("@/components/LandingPage"));

const queryClient = new QueryClient();

const PageLoader = () => null;

const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
  const { isAdmin, loading } = useAuth();

  // Don't block rendering while loading — only gate when we know maintenance is on
  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
  return <>{children}</>;
};

const RootRoute = () => {
  const { user, loading } = useAuth();
  if (loading) return <PageLoader />;
  return user ? <Index /> : <LandingPage />;
};

const App = () => (
  <QueryClientProvider client={queryClient}>
    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
      <AuthProvider>
        <TooltipProvider>
          <Sonner />
          <BrowserRouter>
            <SeoHead />
            <Suspense fallback={<PageLoader />}>
              <Routes>
                {/* Public apply page — outside MaintenanceGate so candidates can always apply */}
                <Route path="/apply/:jobId" element={<Apply />} />
                <Route path="*" element={
                  <MaintenanceGate>
                    <Routes>
                      <Route path="/auth" element={<Auth />} />
                      <Route path="/" element={<RootRoute />} />
                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
                      <Route path="/book-demo" element={<BookDemo />} />
                      <Route path="/request-feature" element={<RequestFeature />} />
                      <Route path="/changelog" element={<Changelog />} />
                      <Route path="/payment/callback" element={<PaymentCallback />} />
                      <Route path="*" element={<NotFound />} />
                    </Routes>
                  </MaintenanceGate>
                } />
              </Routes>
            </Suspense>
            <ChatWidget />
          </BrowserRouter>
        </TooltipProvider>
      </AuthProvider>
    </ThemeProvider>
  </QueryClientProvider>
);

export default App;

