export default function Apply() {
  const { jobId } = useParams<{ jobId: string }>();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [linkedinUrl, setLinkedinUrl] = useState("");
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  // Fetch minimal job info — no auth required via RPC
  const {
    data: job,
    isLoading: jobLoading,
    error: jobError,
  } = useQuery<JobInfo | null>({
    queryKey: ["apply-job-info", jobId],
    queryFn: async () => {
      if (!jobId) return null;
      const { data, error } = await supabase.rpc("get_job_apply_info", {
        p_job_id: jobId,
      });
      if (error) throw new Error(error.message);
      if (!data || (Array.isArray(data) && data.length === 0)) return null;
      const row = Array.isArray(data) ? data[0] : data;
      return row as JobInfo;
    },
    enabled: !!jobId,
    retry: 1,
    staleTime: 60_000,
  });

  const handleFileSelect = (file: File) => {
    if (file.size > MAX_FILE_BYTES) {
      toast.error("File exceeds 10MB limit");
      return;
    }
    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
      return;
    }
    setResumeFile(file);
    setFieldErrors((prev) => ({ ...prev, resume: "" }));
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFileSelect(file);
  };

  const validate = (): boolean => {
    const errors: Record<string, string> = {};
    if (!name.trim()) errors.name = "Name is required";
    if (!email.trim()) errors.email = "Email is required";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
      errors.email = "Enter a valid email address";
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    if (!jobId) {
      toast.error("Invalid application link");
      return;
    }

    setSubmitting(true);
    try {
      const form = new FormData();
      form.append("job_id", jobId);
      form.append("name", name.trim());
      form.append("email", email.trim().toLowerCase());
      if (phone.trim()) form.append("phone", phone.trim());
      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
      if (resumeFile) form.append("resume", resumeFile);

      const { data: sessionData } = await supabase.auth.getSession();
      const headers: Record<string, string> = {
        // Supabase project URL and anon key from env — required even for anon calls
        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
      };
      if (sessionData.session?.access_token) {
        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
      } else {
        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
      }

      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
      const res = await fetch(
        `${supabaseUrl}/functions/v1/submit-application`,
        {
          method: "POST",
          headers,
          body: form,
        }
      );

      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.error || "Failed to submit application");
