function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

const Profile = () => {
  const { user, profile } = useAuth();
  const plan = profile?.plan ?? "free";
  const isPaid = plan !== "free";

  // Fetch usage stats
  const [stats, setStats] = useState<{ totalJobs: number; totalResumes: number; creditsUsed: number } | null>(null);
  const fetchStats = useCallback(async () => {
    if (!user) return;
    try {
      const [jobsRes, usageRes] = await Promise.all([
        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user.id),
        supabase.from("usage_logs").select("credits_used").eq("user_id", user.id),
      ]);
      const jobs = jobsRes.data ?? [];
      const totalJobs = jobs.length;
      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
      setStats({ totalJobs, totalResumes, creditsUsed });
    } catch {
      toast.error("Failed to load activity stats");
    }
  }, [user]);
  useEffect(() => { fetchStats(); }, [fetchStats]);

