const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

